#include <stdint.h>
#include "stm32f103x8.h"
#include "GPIO_driver.h"
#include "RCC_driver.h"
#include "EXTI_Driver.h"
#include "NVIC_Driver.h"
#include "USART_Driver.h"

GPIO_PINCONFIG_T led =
{
	.pin = 14,
	.mode = GPIO_OUT_PUPL_MODE_50,
	.alternatefunc = 0
};

GPIO_PINCONFIG_T PushButton =
{
		.pin = 0,
		.mode = GPIO_PUPD_INPUT_MODE,
		.alternatefunc = 0
};

#if !defined(__SOFT_FP__) && defined(__ARM_FP)
  #warning "FPU is not initialized, but the project is compiling for an FPU. Please initialize the FPU before use."
#endif

USART_Struct_T Usart2Struct =
{
		.baudrate = 9600,
		.parity = USART_PARITY_NONE,
		.stopBits = USART_STOPBITS_1,
		.usartID = USART2_ID,
		.wordlength = USART_WORDLENGTH_8B
};
void delay(void){

	for(uint32_t i=0; i<1777777; i++);
}
void interrupt_program(){

	   /*enable push button clock connected to PA0*/
		RCC_Enable_GPIO(GPIOA);

		/*enable push button clock connected to PA0*/
		RCC_Enable_GPIO(GPIOC);

		/*Initializes LED Pin*/
		GPIO_Init(GPIOA, &PushButton);

		/*Initializes LED Pin*/
		GPIO_Init(GPIOC, &led);

		/*Enable Line interrupt*/
		EXTI_EnableInterrupt(0, EXTI_TRIGGER_RISING);

		/*Enable interrupt for EXTI0*/
		NVIC_EnableIRQ(EXTI0_IRQn);

}
int main(void)
{

	/*uncomment to execute interrupt program*/
	void interrupt_program();




}
