void EXTI1_IRQHandler()
{
    if(EXTI_IsPending(EXTI0_IRQn)==1)
    {
    	GPIO_TogglePin(GPIOC, 13);
    	EXTI_ClearPending(EXTI0_IRQn);
    }
}
